class Thread:
    def __init__(self, wcet):
        self.wcet = wcet

class Segment:
    def __init__(self, threads):
        self.threads = threads
        self.m_j = len(threads)
        self.C_j = sum(t.wcet for t in threads) # Single-core WCET
        self.LC_j = max(t.wcet for t in threads) # Min execution time (infinite cores)

class Task:
    def __init__(self, segments, period, deadline):
        self.segments = segments
        self.T = period
        self.D = deadline
        self.s = len(segments)
        self.m = max(s.m_j for s in segments) # Max parallelism
        self.C = sum(s.C_j for s in segments) # Total single-core WCET
        self.LC = sum(s.LC_j for s in segments) # Total min execution time
        self.U = self.C / self.T

    def is_constrained_deadline(self):
        return self.D <= self.T

    def is_feasible_min_exec_time(self):
        return self.LC <= self.D

def calculate_traditional_interference_k(task_k, interval_a, interval_b, schedule):
    interference_k = 0
    for t in range(interval_a, interval_b):
        if schedule.is_task_ready(task_k, t) and not schedule.is_task_executing(task_k, t):
            if schedule.is_processor_occupied_by_higher_priority(task_k, t):
                interference_k += 1
    return interference_k

def calculate_traditional_interference_i_k(task_i, task_k, interval_a, interval_b, schedule):
    interference_i_k = 0
    for t in range(interval_a, interval_b):
        if schedule.is_task_executing(task_i, t) and schedule.is_task_ready(task_k, t) and not schedule.is_task_executing(task_k, t):
            interference_i_k += 1
    return interference_i_k

def check_traditional_interference_relation(task_k, task_set, m, interval_a, interval_b, schedule):
    total_interference_k = calculate_traditional_interference_k(task_k, interval_a, interval_b, schedule)
    sum_individual_interference = 0
    for task_i in task_set:
        sum_individual_interference += calculate_traditional_interference_i_k(task_i, task_k, interval_a, interval_b, schedule)
    return total_interference_k == (1.0 / m) * sum_individual_interference

def calculate_critical_thread_interference(critical_thread, task_k, segment_u, interval_a, interval_b, schedule):
    interference = 0
    for t in range(interval_a, interval_b):
        if schedule.is_thread_ready(critical_thread, t) and not schedule.is_thread_executing(critical_thread, t):
            # Check if blocked by higher-priority threads (inter-task) or other threads of same task (intra-task)
            if schedule.is_blocked_by_higher_priority_or_intra_task(critical_thread, task_k, t):
                interference += 1
    return interference

def calculate_total_critical_interference_k(task_k, interval_a, interval_b, schedule):
    total_interference = 0
    for segment_u in task_k.segments:
        critical_thread = segment_u.identify_critical_thread(interval_a, schedule) # Conceptual
        total_interference += calculate_critical_thread_interference(critical_thread, task_k, segment_u, interval_a, interval_b, schedule)
    return total_interference

def calculate_p_depth_critical_interference_i_k(task_i, task_k, p, interval_a, interval_b, schedule):
    # This is a conceptual function, actual calculation is complex
    p_depth_interference = 0
    for t in range(interval_a, interval_b):
        if schedule.is_critical_thread_k_ready_but_not_executing(task_k, t):
            num_threads_i_executing = schedule.count_threads_executing(task_i, t)
            if num_threads_i_executing == p:
                p_depth_interference += 1
    return p_depth_interference

# The relation:
# I_k_a_b = (1.0 / m) * sum(sum(calculate_p_depth_critical_interference_i_k(tau_i, tau_k, p, a, b, schedule) * p 
#                                for p in range(1, m + 1)) 
#                           for tau_i in tau_set)

def calculate_at_least_p_depth_critical_interference(task_i, task_k, p, interval_a, interval_b, m, schedule):
    at_least_p_interference = 0
    for q in range(p, m + 1):
        at_least_p_interference += calculate_p_depth_critical_interference_i_k(task_i, task_k, q, interval_a, interval_b, schedule)
    return at_least_p_interference

def check_schedulability_lemma1(task_set, m, scheduler):
    for task_k in task_set:
        # Conceptual: find worst-case job J_k_star and its window [r_k_star, d_k_star)
        r_k_star, d_k_star = scheduler.find_worst_case_job_window(task_k)

        interference_k = calculate_total_critical_interference_k(task_k, r_k_star, d_k_star, scheduler)
        available_slack = task_k.D - task_k.LC

        if interference_k > available_slack:
            return False # Task k is not schedulable
    return True # All tasks are schedulable

def check_schedulability_theorem1(task_set, m, scheduler):
    for task_k in task_set:
        r_k_star, d_k_star = scheduler.find_worst_case_job_window(task_k) # Conceptual
        available_slack = task_k.D - task_k.LC

        total_bounded_interference_sum = 0
        for task_i in task_set:
            for p in range(1, m + 1):
                # Conceptual: calculate I_plus_i_k(p, r_k_star, d_k_star)
                # This would involve detailed simulation or analytical bounds
                i_plus_i_k_p = scheduler.calculate_i_plus_i_k(task_i, task_k, p, r_k_star, d_k_star)
                total_bounded_interference_sum += min(i_plus_i_k_p, available_slack)

        if total_bounded_interference_sum >= m * available_slack:
            return False # Task k is not schedulable
    return True # All tasks are schedulable

def calculate_workload(task_i, interval_a, interval_b, schedule):
    workload = 0
    for t in range(interval_a, interval_b):
        if schedule.is_task_executing(task_i, t):
            workload += 1
    return workload

def calculate_p_depth_workload_i_k(task_i, task_k, p, interval_a, interval_b, schedule):
    p_depth_workload = 0
    for t in range(interval_a, interval_b):
        num_threads_i_executing = schedule.count_threads_executing(task_i, t)
        if num_threads_i_executing == p:
            # Conceptual: check if all p threads have higher priority than tau_k's critical thread
            if schedule.all_p_threads_higher_priority(task_i, task_k, t):
                p_depth_workload += 1
    return p_depth_workload

def calculate_at_least_p_depth_workload(task_i, task_k, p, interval_a, interval_b, m, schedule):
    at_least_p_workload = 0
    for q in range(p, m + 1):
        at_least_p_workload += calculate_p_depth_workload_i_k(task_i, task_k, q, interval_a, interval_b, schedule)
    return at_least_p_workload

def calculate_BD_plus_i_k(task_i, p, D_k):
    num_full_jobs = D_k // task_i.T
    segment_LC_sum = 0
    for segment in task_i.segments:
        if segment.m_j >= p:
            segment_LC_sum += segment.LC_j
    return num_full_jobs * segment_LC_sum

def calculate_CI_plus_i_k(task_i, p, L):
    if L <= 0:
        return 0

    segment_LC_sum_for_p = [s.LC_j for s in task_i.segments if s.m_j >= p]
    total_LC_i_for_p = sum(segment_LC_sum_for_p)

    if L > task_i.LC: # If L is very large, it covers all segments that can contribute
        return total_LC_i_for_p

    # Find h: earliest segment fully included in L
    current_L_consumed = 0
    h = 0
    for idx, segment in enumerate(task_i.segments):
        if current_L_consumed + segment.LC_j <= L:
            current_L_consumed += segment.LC_j
            h = idx + 1 # h is 1-indexed
        else:
            break

    carry_in_workload = 0
    # Sum full segments from h to s_i
    for j in range(h, task_i.s):
        if task_i.segments[j].m_j >= p:
            carry_in_workload += task_i.segments[j].LC_j

    # Handle partial segment (h-1)
    if h > 0:
        segment_h_minus_1 = task_i.segments[h-1]
        remaining_L = L - current_L_consumed
        if segment_h_minus_1.m_j >= p:
            carry_in_workload += min(remaining_L, segment_h_minus_1.LC_j) # Only add what fits and contributes

    return carry_in_workload

def calculate_W_star_k_k(task_k, p, D_k):
    intra_task_workload = 0
    for segment in task_k.segments:
        if segment.m_j >= (p + 1):
            intra_task_workload += segment.LC_j
    return intra_task_workload

def check_schedulability_lemma5(task_set, m):
    for task_k in task_set:
        # Assumption: m >= task_i.m for all tasks
        if not all(m >= t.m for t in task_set): 
            # This check is for the lemma's assumption, not the final theorem
            # In practice, this function would only be called if the assumption holds
            pass 

        available_slack = task_k.D - task_k.LC
        total_workload_bound = 0

        # Inter-task workload
        for task_i in task_set:
            if task_i == task_k:
                continue
            for p_val in range(1, task_i.m + 1):
                w_star_i_k_p = calculate_W_star_i_k(task_i, p_val, task_k.D)
                total_workload_bound += min(w_star_i_k_p, available_slack)

        # Intra-task workload
        for p_val in range(1, task_k.m + 1):
            w_star_k_k_p = calculate_W_star_k_k(task_k, p_val, task_k.D)
            total_workload_bound += min(w_star_k_k_p, available_slack)

        if total_workload_bound > m * available_slack:
            return False # Task k is not schedulable
    return True # All tasks are schedulable

